import data from "../data/shortcodes.json";
import { applySkinTone } from "./skin-tone";
import type { EmojiEntry, SkinTone } from "./types";

export type InsertFormat = "emoji" | "github" | "slack";

// Generated by scripts/build-shortcodes.mjs: emoji -> [github, slack], "" = no code.
const CODES = data as unknown as Record<string, [string, string]>;

export function parseInsertFormat(value: unknown): InsertFormat {
  return value === "github" || value === "slack" ? value : "emoji";
}

/** The shortcode without colons, or null when the set has none. */
export function shortcodeFor(entry: EmojiEntry, set: "github" | "slack"): string | null {
  const code = CODES[entry.emoji]?.[set === "github" ? 0 : 1];
  return code ? code : null;
}

export function formatEmoji(entry: EmojiEntry, format: InsertFormat, skinTone: SkinTone): string {
  if (format !== "emoji") {
    const code = shortcodeFor(entry, format);
    if (code) return `:${code}:`;
  }
  return applySkinTone(entry, skinTone);
}

export function formatSequence(entries: EmojiEntry[], format: InsertFormat, skinTone: SkinTone): string {
  return entries.map((e) => formatEmoji(e, format, skinTone)).join(format === "emoji" ? "" : " ");
}
